plugins {
  id 'jacoco'
  id 'com.gradleup.shadow' version '8.3.8'
  id 'org.jetbrains.kotlin.jvm' version '2.0.0'
  id 'io.github.gradle-nexus.publish-plugin' version '2.0.0'
