          if (!annos.isEmpty()) {
            buffer.appendCastTypeName(descriptor == null ? md.ret : descriptor.returnType, annos, writtenAnnotations);
          } else {
            buffer.appendCastTypeName(descriptor == null ? md.ret : descriptor.returnType);
