          boolean useDescriptor = descriptor != null && !descriptor.exceptionTypes.isEmpty();
          for (int i = 0; i < (attr == null ? descriptor.exceptionTypes.size() : attr.getThrowsExceptions().size()); i++) {
            if (i > 0) {
