    // TODO: optimize
    //tracer.setCurrentSourceLine(buffer.countLines(start_index_method));

    if (!hiddenRecordMethod && hideMethod && retainMethod(node, mt, (String)DecompilerContext.getProperty(IFernflowerPreferences.METHOD_TO_DECOMPILE))) {
      hideMethod = false;
    }
    return !hideMethod;
