  private static boolean retainField(StructClass owner, StructField field) {
    ReferenceAwareSyntheticRetention retention = ReferenceAwareSyntheticRetention.getCurrent();
    return retention != null && retention.retainField(owner, field);
  }

  private static boolean retainMethod(ClassNode node, StructMethod method, String methodToDecompile) {
    if (!methodToDecompile.isEmpty()) {
      return false;
    }

    ReferenceAwareSyntheticRetention retention = ReferenceAwareSyntheticRetention.getCurrent();
    return retention != null && retention.retainMethod(node.classStruct, method);
  }

